  "gas.ethUsd": "{eth} ETH · {usd}",
  "gas.gwei": "{v} gwei",
  "gas.math": "{units} de gas × ({base} de tarifa base + {tip} de propina) gwei = {gwei} gwei = {eth} ETH — el {pct} % se quema.",
  "gas.valuetextBase": "tarifa base de {base} gwei; pagas {total} ETH",
